const rawEmail = String(
  $('15 - Set - Payload CRM1').first().json.email || ''
).trim();

// Extraer solamente una dirección de email válida.
// Funciona aunque Gmail entregue:
// "Waldemar Waller <wald.waller@gmail.com>"
const emailMatch = rawEmail.match(
  /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i
);

// Si no encontramos un email válido, detenemos el flujo
// con un error entendible en lugar de mandar basura a Zoho.
if (!emailMatch) {
  throw new Error(
    `No se pudo extraer un email válido. Valor recibido: "${rawEmail}"`
  );
}

const targetEmail = emailMatch[0]
  .trim()
  .toLowerCase();

// Todos los contactos recibidos desde Zoho
const contacts = $input
  .all()
  .map(item => item.json)
  .filter(contact =>
    contact &&
    Object.keys(contact).length > 0
  );

// Buscar coincidencia exacta por Email
const match = contacts.find(contact => {
  const contactEmail = String(
    contact.Email || ''
  )
    .trim()
    .toLowerCase();

  return contactEmail === targetEmail;
});

// Devolver siempre un único objeto normalizado
return [
  {
    json: {
      found: Boolean(match),
      contact_id: match?.id || '',
      email: targetEmail,
      contact: match || null,
      total_contacts_received: contacts.length
    }
  }
];
